/* Same routine as FUN_L05_00307010, with this level's data offsets. */
void accumulate_moby_frames_in_group_bounds(struct Moby *moby) __asm__("FUN_L16_002cfc00");

void accumulate_moby_frames_in_group_bounds(struct Moby *moby) {
    char *data = (char *)moby->pvars;
    struct Hero *hero_state = &hero;
    float displacement_vector[4];
    char *enumerated_moby;
    char *group_candidate_moby;
    char *other;
    char *od;

    if (hero_state->race_time_frames < scale_game_frames(0xB4)) {
        return;
    }
    if (!tick_countdown_32((int *)(data + 0x2DC))) {
        return;
    }
    other = ((char *)hero_state->hoverboard_moby);
    if (!other) {
        return;
    }
    od = *(char **)(other + 0x78);
    if (*(int *)(od + 0x44) != -1) {
        get_first_moby_in_group((int *)&enumerated_moby, *(int *)(od + 0x44), 0, 0);
        while (enumerated_moby) {
            if (*(short *)(enumerated_moby + 0xA6) == 0x473) {
                float adjusted_position[4];
                float m[16];
                char *candidate_moby = enumerated_moby;
                qcopy(adjusted_position, data + 0x260);
                adjusted_position[2] += 0.8f;
                subtract_vector_xyz(displacement_vector, candidate_moby + 0x10, adjusted_position);
                if (!(8.0f < vector_length_xyz(displacement_vector))) {
                    set_identity_matrix(m);
                    transpose_rotation_matrix(m, enumerated_moby + 0xC0);
                    transform_vector(displacement_vector, displacement_vector, m);
                    if (absolute_float(displacement_vector[0]) < 0.5f && absolute_float(displacement_vector[1]) < 2.5f &&
                        absolute_float(displacement_vector[2]) < 2.5f) {
                        *(unsigned short *)(data + 0x2F6) += scale_game_frames(0x78);
                        *(int *)(data + 0x2DC) = scale_game_frames(0x3C);
                    }
                }
            }
            get_next_moby_in_group((int *)&enumerated_moby, (int)enumerated_moby, 0, 0);
        }
    }
    if (*(int *)(od + 0x48) != -1) {
        get_first_moby_in_group((int *)&group_candidate_moby, *(int *)(od + 0x48), 0, 0);
        while (group_candidate_moby) {
            if (*(short *)(group_candidate_moby + 0xA6) == 0x474) {
                float m[16];
                subtract_vector_xyz(displacement_vector, group_candidate_moby + 0x10, data + 0x260);
                if (!(8.0f < vector_length_xyz(displacement_vector))) {
                    set_identity_matrix(m);
                    transpose_rotation_matrix(m, group_candidate_moby + 0xC0);
                    transform_vector(displacement_vector, displacement_vector, m);
                    if (absolute_float(displacement_vector[0]) < 2.8f && absolute_float(displacement_vector[1]) < 1.4f &&
                        absolute_float(displacement_vector[2]) < 0.5f) {
                        *(unsigned short *)(data + 0x2F6) += scale_game_frames(0x78);
                        *(int *)(data + 0x2DC) = scale_game_frames(0x3C);
                    }
                }
            }
            get_next_moby_in_group((int *)&group_candidate_moby, (int)group_candidate_moby, 0, 0);
        }
    }
}

